
using UnityEngine;

/*
 * WalkSimulator moves the camera along the path of blocks generated by EndlessRunnerEngine.
 * For debugging purposes when not using VR headset.
 * It requires a reference to the EndlessRunnerEngine object, and will move the camera along the path at a constant speed.
 */
public class WalkSimulator : MonoBehaviour
{
    public GameObject endlessRunnerObject;
    private EndlessRunnerEngine eng;

    private float height = 1.5f;
    public float speed = 0.5f; // meters per second along the path

    private Block currentBlock;
    private float distanceIntoBlock;

    void Awake()
    {
        //Get access to the EndlessRunnerEngine component
        if (endlessRunnerObject != null) eng = endlessRunnerObject.GetComponent<EndlessRunnerEngine>();
        else Debug.LogError("WalkSimulator: endlessRunnerObject is not set.");
    }

    void Start()
    {
    }

    void Update()
    {
        if (endlessRunnerObject == null || eng == null || eng.head == null) 
        {
            Debug.Log("endlessRunnerObject:"+endlessRunnerObject+", eng:"+eng+", eng.head:"+eng.head+", currentBlock:"+currentBlock);
            return;
        }

        if (eng != null) {
            currentBlock = eng.CurrentBlock;
        } else return;

        distanceIntoBlock += speed * Time.deltaTime;

        //Debug.Log("WalkSimulator: distanceIntoBlock = " + distanceIntoBlock + ", currentBlock.Length = " + currentBlock.Length);
        // Advance to the next block once we've walked past the end of the current one.
        while (currentBlock.Next != null && distanceIntoBlock >= currentBlock.Length)
        {
            distanceIntoBlock -= currentBlock.Length;
            currentBlock = currentBlock.Next;
        }
        distanceIntoBlock = Mathf.Clamp(distanceIntoBlock, 0f, currentBlock.Length);

        //Follow the block's actual path: straight for the first half, then bending to the exit
        //direction over the second half for turn blocks (a no-op for straight blocks).
        Vector3 forward = new Vector3(currentBlock.Direction.x, 0f, currentBlock.Direction.y);
        Vector3 exitForward = new Vector3(currentBlock.ExitDirection.x, 0f, currentBlock.ExitDirection.y);
        float half = currentBlock.Length / 2f;

        Vector3 newPos;
        if (distanceIntoBlock <= half)
        {
            newPos = currentBlock.StartPosition + forward * distanceIntoBlock;
        }
        else
        {
            Vector3 pivot = currentBlock.StartPosition + forward * half;
            newPos = pivot + exitForward * (distanceIntoBlock - half);
        }
        newPos += Vector3.up * height;

        // Smoothly rotate to face the exit direction over the second half of the block.
        float turnFraction = Mathf.Clamp01((distanceIntoBlock - half) / half);
        Vector3 forwardInterpolated = Vector3.Lerp(forward, exitForward, turnFraction).normalized;

        // Apply position and rotation to the camera (head) in the EndlessRunnerEngine
        eng.head.transform.position = newPos;
        eng.head.transform.rotation = Quaternion.LookRotation(forwardInterpolated, Vector3.up)*Quaternion.Euler(20,0,0);
    }
}